import json
import os
import pandas as pd
import numpy as np

DATA_FILE = "/home/chs/Work/tga_plot/tests/inputs/blank_rows_on_top.xlsx"

df = pd.read_excel(DATA_FILE, sheet_name="Sheet1", header=7, usecols="C:E")
df.columns = [str(c).strip() for c in df.columns]

x = pd.to_numeric(df.iloc[:, 0], errors="coerce")
y1 = pd.to_numeric(df.iloc[:, 1], errors="coerce")
y2 = pd.to_numeric(df.iloc[:, 2], errors="coerce")
valid = x.notna() & y1.notna() & y2.notna()
x, y1, y2 = x[valid], y1[valid], y2[valid]

data1 = [[float(a), float(b)] for a, b in zip(x, y1)]
data2 = [[float(a), float(-b)] for a, b in zip(x, y2)]

residue_idx = (x - 800).abs().idxmin()
residue_temp = float(x.loc[residue_idx])
residue_value = float(y1.loc[residue_idx])

peak_mask = x > 150
if peak_mask.any():
    peak_idx = y2[peak_mask].idxmin()
    peak_temp = float(x.loc[peak_idx])
    peak_value = float(-y2.loc[peak_idx])
else:
    peak_idx = y2.idxmin()
    peak_temp = float(x.loc[peak_idx])
    peak_value = float(-y2.loc[peak_idx])

option = {
